#!/usr/bin/env python3
"""Run one owned validation process group with retained resource evidence."""

import argparse
import json
import os
from pathlib import Path
import resource
import signal
import subprocess
import sys
import time


def available_kib():
    for line in Path('/proc/meminfo').read_text().splitlines():
        if line.startswith('MemAvailable:'):
            return int(line.split()[1])
    raise RuntimeError('MemAvailable unavailable; cannot enforce memory guard')


def group_memory(group):
    members = []
    for path in Path('/proc').iterdir():
        if not path.name.isdigit():
            continue
        try:
            fields = (path / 'stat').read_text().rsplit(')', 1)[1].split()
            if int(fields[2]) != group:
                continue
            status = dict(line.split(':', 1) for line in (path / 'status').read_text().splitlines())
            members.append({
                'pid': int(path.name),
                'name': status['Name'].strip(),
                'rss_kib': int(status.get('VmRSS', '0 kB').split()[0]),
                'vas_kib': int(status.get('VmSize', '0 kB').split()[0]),
                'threads': int(status.get('Threads', '0').strip()),
            })
        except (FileNotFoundError, ProcessLookupError, PermissionError):
            continue
    return members


def child_limits():
    resource.setrlimit(resource.RLIMIT_CORE, (0, 0))
    cap = 32 * 1024**3
    resource.setrlimit(resource.RLIMIT_AS, (cap, cap))


def stop_group(child):
    if child is None:
        return
    try:
        os.killpg(child.pid, signal.SIGTERM)
    except ProcessLookupError:
        return
    try:
        child.wait(timeout=3)
    except subprocess.TimeoutExpired:
        pass
    try:
        os.killpg(child.pid, signal.SIGKILL)
    except ProcessLookupError:
        pass
    child.wait()


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--evidence', type=Path, required=True)
    parser.add_argument('command', nargs=argparse.REMAINDER)
    args = parser.parse_args()
    command = args.command
    if command and command[0] == '--':
        command = command[1:]
    if not command:
        parser.error('a command is required')
    args.evidence.mkdir(parents=True, exist_ok=False)
    context = {
        'command': command, 'cwd': str(Path.cwd()),
        'address_space_cap_bytes': 32 * 1024**3,
        'aggregate_rss_cap_kib': 5 * 1024**2,
        'mem_available_minimum_kib': 2 * 1024**2,
        'sample_interval_seconds': 0.2,
        'disk_reserves_bytes': {'/tmp': 512 * 1024**2, '/dev/shm': 512 * 1024**2, '/workspace': 64 * 1024**2},
        'env': {key: os.environ.get(key) for key in (
            'CARGO_HOME', 'RUSTUP_HOME', 'CARGO_TARGET_DIR', 'CARGO_BUILD_JOBS',
            'RUSTFLAGS', 'RUST_MIN_STACK', 'CARGO_PROFILE_DEV_DEBUG',
            'CARGO_PROFILE_TEST_DEBUG', 'CARGO_INCREMENTAL',
        )},
    }
    (args.evidence / 'context.json').write_text(json.dumps(context, indent=2) + '\n')
    start = time.monotonic()
    initial_available = available_kib()
    lowest_available = initial_available
    peak_rss = peak_vas = 0
    stop_reason = None
    received_signal = None
    child = None
    result_code = 125

    def on_signal(signum, _frame):
        nonlocal received_signal
        received_signal = signum

    signal.signal(signal.SIGTERM, on_signal)
    signal.signal(signal.SIGINT, on_signal)
    try:
        if initial_available < context['mem_available_minimum_kib']:
            stop_reason = 'Memory guard refused to start: less than 2 GiB available'
        else:
            child = subprocess.Popen(command, start_new_session=True, preexec_fn=child_limits)
            with (args.evidence / 'memory.jsonl').open('x') as trace:
                while child.poll() is None:
                    members = group_memory(child.pid)
                    available = available_kib()
                    rss = sum(member['rss_kib'] for member in members)
                    vas = sum(member['vas_kib'] for member in members)
                    lowest_available = min(lowest_available, available)
                    peak_rss, peak_vas = max(peak_rss, rss), max(peak_vas, vas)
                    trace.write(json.dumps({
                        'elapsed_seconds': round(time.monotonic() - start, 3),
                        'mem_available_kib': available, 'rss_kib': rss,
                        'vas_kib': vas, 'members': members,
                        'disk_free_bytes': {p: os.statvfs(p).f_bavail * os.statvfs(p).f_frsize for p in context['disk_reserves_bytes']},
                    }) + '\n')
                    trace.flush()
                    if received_signal is not None:
                        stop_reason = f'Validation supervisor received signal {received_signal}'
                    elif available < context['mem_available_minimum_kib']:
                        stop_reason = 'Memory guard: MemAvailable below 2 GiB'
                    elif rss > context['aggregate_rss_cap_kib']:
                        stop_reason = 'Memory guard: owned process RSS exceeded 5 GiB'
                    if stop_reason is None and any(os.statvfs(p).f_bavail * os.statvfs(p).f_frsize < floor for p, floor in context['disk_reserves_bytes'].items()):
                        stop_reason = 'Disk guard: a validation volume fell below its recorded reserve'
                    if stop_reason is not None:
                        break
                    time.sleep(0.2)
            if stop_reason is None:
                result_code = child.wait()
    finally:
        stop_group(child)
        result = {
            'duration_seconds': round(time.monotonic() - start, 3),
            'initial_mem_available_kib': initial_available,
            'lowest_mem_available_kib': lowest_available,
            'peak_aggregate_rss_kib': peak_rss,
            'peak_aggregate_vas_kib': peak_vas,
            'stop_reason': stop_reason,
            'child_returncode': None if child is None else child.returncode,
            'supervisor_returncode': result_code,
        }
        (args.evidence / 'result.json').write_text(json.dumps(result, indent=2) + '\n')
        print('VALIDATION_RESOURCE_RESULT ' + json.dumps(result), flush=True)
    return result_code if result_code >= 0 else 128 - result_code


if __name__ == '__main__':
    sys.exit(main())

